const families={english:['Fredoka, sans-serif','cursive','Georgia, serif','Trebuchet MS, sans-serif','Arial Black, sans-serif','Brush Script MT, cursive','Impact, sans-serif','Courier New, monospace','Comic Sans MS, cursive','Times New Roman, serif','Verdana, sans-serif','Palatino, serif'],japanese:["'Zen Maru Gothic', sans-serif","serif","cursive","sans-serif","'Yu Mincho',serif","'Meiryo',sans-serif","'Yu Gothic',sans-serif"]};
let mode='english',selected=0;const input=document.querySelector('#font-input'),options=document.querySelector('#font-options'),preview=document.querySelector('#font-preview'),selection=document.querySelector('#font-selection');
function label(){return (mode==='english'?'英語':'日本語')+' '+['①','②','③','④','⑤','⑥','⑦','⑧','⑨','⑩','⑪','⑫'][selected]}
function render(){options.innerHTML='';families[mode].forEach((family,index)=>{const button=document.createElement('button');button.textContent=['①','②','③','④','⑤','⑥','⑦','⑧','⑨','⑩','⑪','⑫'][index];button.style.fontFamily=family;if(index===selected)button.classList.add('selected');button.onclick=()=>{selected=index;render()};options.append(button)});preview.textContent=input.value||'文字を入力';preview.style.fontFamily=families[mode][selected];selection.textContent=label()+' を選択中'}
document.querySelectorAll('.font-tabs button').forEach(button=>button.onclick=()=>{mode=button.dataset.mode;selected=0;document.querySelectorAll('.font-tabs button').forEach(x=>x.classList.remove('selected'));button.classList.add('selected');render()});input.oninput=render;document.querySelector('#copy-font').onclick=async()=>{const text='【バルーン文字の希望】\nフォント：'+label()+'\n入れたい文字：'+(input.value||'未入力');try{await navigator.clipboard.writeText(text);document.querySelector('#copy-font').textContent='コピーしました！';setTimeout(()=>document.querySelector('#copy-font').textContent='選んだ内容をコピー',1600)}catch{alert(text)}};render();
